import RealityKit
import UIKit

// §7b transition flash — a brief full-view fade that masks a scene change. Kept from the
// (now retired) generated L1–L4 pipeline because the spatial-image scene system still uses
// it to mask a jump/select between skies. Everything else that lived here — the generated
// far backdrop, L2 nebula (splat/particle), L3 star volume, L4 phenomena — was removed when
// the app moved to a pre-rendered stereo-image library (see SpatialImageEnvironment).
// Fades to BLACK, not white (device round 7). A white flash masks a change by
// saturating, but between two dark deep-space scenes it reads as a jolt — the eye is
// dark-adapted and gets slammed to full brightness and back. Black masks just as
// completely (alpha 1 fully occludes either way) and costs the viewer nothing.
// Type names still say "Whiteout" so this stays a one-file change; see FADE_TINT.
struct WhiteoutComponent: Component {
    var active = false
    var elapsed: TimeInterval = 0
    var fadeIn: TimeInterval = 0.25
    var hold: TimeInterval = 0.12
    var fadeOut: TimeInterval = 0.45
    var total: TimeInterval { fadeIn + hold + fadeOut }
}

/// 0 = black, 1 = white. One constant, used by both the per-frame tint and the initial
/// material, so they can never disagree.
let FADE_TINT: CGFloat = 0

struct WhiteoutSystem: System {
    static let query = EntityQuery(where: .has(WhiteoutComponent.self))
    init(scene: Scene) {}
    func update(context: SceneUpdateContext) {
        MainActor.assumeIsolated {
            for e in context.entities(matching: Self.query, updatingSystemWhen: .rendering) {
                guard var c = e.components[WhiteoutComponent.self], c.active,
                      let me = e as? ModelEntity else { continue }
                c.elapsed += context.deltaTime
                var a: Float
                if c.elapsed < c.fadeIn {
                    a = Float(c.elapsed / c.fadeIn)                                   // fade to black
                } else if c.elapsed < c.fadeIn + c.hold {
                    a = 1                                                            // peak (swap happens here)
                } else if c.elapsed < c.total {
                    a = Float(1 - (c.elapsed - c.fadeIn - c.hold) / c.fadeOut)         // reveal new env
                } else {
                    a = 0; c.active = false
                }
                a = max(0, min(1, a))
                var mat = UnlitMaterial()
                mat.color = .init(tint: UIColor(white: FADE_TINT, alpha: CGFloat(a)), texture: nil)
                mat.blending = .transparent(opacity: 1.0)
                me.model?.materials = [mat]
                e.components[WhiteoutComponent.self] = c
            }
        }
    }

    // Inward sphere just inside all content; alpha 0 until a jump/select flashes it (§7b).
    @MainActor
    static func makeEntity() -> ModelEntity {
        var mat = UnlitMaterial()
        mat.color = .init(tint: UIColor(white: FADE_TINT, alpha: 0), texture: nil)
        mat.blending = .transparent(opacity: 1.0)
        let e = ModelEntity(mesh: .generateSphere(radius: 1.5), materials: [mat])
        e.name = "Whiteout"
        e.scale.z = -1   // render the inside
        e.components.set(WhiteoutComponent())
        return e
    }
}

import SwiftUI
import RealityKit
import ARKit
import QuartzCore
import simd

/// App-wide observable state. The generated L1–L4 universe was retired in favour of a fixed
/// library of pre-rendered stereo skies, so this is now just: which sky is showing, plus the
/// hooks the immersive scene needs to swap it. Spec: §7a (scene selection), §7e (saved Places).
@Observable
@MainActor
final class AppModel {
    static let immersiveSpaceID = "FloatSpace"

    enum ImmersionState { case closed, opening, open }
    var immersion: ImmersionState = .closed

    /// True once the FIRST sky has finished loading into the immersive space — the signal
    /// SplashView fades out on. Deliberately one-way: `immersion == .open` only means the
    /// space exists, and the real wait is decoding a ~100 MB stereo HEIC into two 12288×6144
    /// textures. Never reset on a scene change — swapping skies is masked by the §7b
    /// whiteout, and re-showing the launch view mid-session would read as a crash.
    var sceneReady = false

    /// Index of the current sky in `SpatialImageEnvironment.catalog`. Restored across
    /// launches by NAME (not index) so catalog additions/reorders don't shift the selection.
    var currentScene: Int = 0

    private static let lastSceneKey = "lastSceneName"

    init() {
        if let name = UserDefaults.standard.string(forKey: Self.lastSceneKey),
           let idx = SpatialImageEnvironment.catalog.firstIndex(where: { $0.name == name }) {
            currentScene = idx
        }
    }

    /// Global animation clock (§5, foundational). Retained for future slow motion (e.g. a
    /// gentle backdrop yaw); nothing reads it while the scene is a static sphere.
    let clock = AnimationClock()

    /// Saved "Places" (§7e).
    var savedLocations: [SavedLocation] = []

    /// Set by ImmersiveView once the scene builds.
    var sceneContainer: Entity?   // persistent container
    var sceneRoot: Entity?        // the SpatialImageEnvironment sphere container
    var whiteout: Entity?         // §7b flash overlay

    /// ARKit world tracking, handed over by ImmersiveView once its session is running.
    /// Its only consumer is `recenter()` — the device anchor is the head pose.
    var worldTracking: WorldTrackingProvider?

    /// First sky, decoded BEFORE the immersive space opens so the space is never empty.
    /// `ImmersiveView` consumes this once and clears it; nil afterwards, and nil if the
    /// preload failed (in which case the view falls back to loading in place).
    var preparedSky: ModelEntity?

    /// Decode the startup sky while the launcher/splash is still the only thing on screen.
    /// Ordering matters more than it looks: opening the space first and loading into it
    /// afterwards leaves the user staring into an empty black sphere for the length of a
    /// ~100 MB stereo HEIC decode. Doing it in this order costs the same wall time but
    /// spends it on a screen that has something to look at.
    func prepareFirstSky() async {
        guard preparedSky == nil else { return }
        preparedSky = await SpatialImageEnvironment.prepare(index: currentScene)
    }

    // MARK: - Recenter

    /// Yaw (radians, about +Y) currently applied to `sceneRoot` so the sky faces the user.
    /// Session-only — deliberately not persisted, and deliberately NOT reset by a scene
    /// change: it describes which way the user's body is pointing, not which sky is up.
    /// Living on the persistent `sceneRoot` container means a swap inherits it for free.
    private(set) var recenterYaw: Float = 0

    /// Make the direction the user is currently facing the scene's forward direction.
    ///
    /// **Yaw only.** Only the Y-axis component of the head pose is used; pitch and roll are
    /// discarded. The backdrop is a stereo 360 sphere whose per-eye disparity is baked
    /// horizontally in equirect space, so rotating content about any other axis tilts that
    /// baked disparity axis off the viewer's interocular axis and introduces vertical
    /// disparity — nauseating, not merely wrong-looking (§9, comfort is a gate).
    ///
    /// **Snaps, never animates.** Slewing the whole visual field is a textbook vection
    /// trigger; an instant cut is the comfortable option (§9). The camera does not move —
    /// only scene content rotates.
    /// Returns whether the recenter was actually applied. The launch auto-recenter polls on
    /// this: the device anchor is not tracked the instant the provider starts, so "did it
    /// take" has to be answerable rather than silently no-op.
    @discardableResult
    func recenter() -> Bool {
        guard let sceneRoot,
              let device = worldTracking?.queryDeviceAnchor(atTimestamp: CACurrentMediaTime()),
              device.isTracked
        else { return false }

        // Head forward is the -Z column of the device transform. Keep only its horizontal
        // (x, z) part — that projection IS the yaw-only extraction.
        let m = device.originFromAnchorTransform
        let forward = SIMD2<Float>(-m.columns.2.x, -m.columns.2.z)
        // Degenerate when looking near-straight up or down: there is no meaningful facing
        // direction, so ignore the press rather than snap to an arbitrary heading.
        guard simd_length_squared(forward) > 1e-6 else { return false }

        // forward == (-sin θ, -cos θ) for a yaw of θ about +Y.
        recenterYaw = atan2(-forward.x, -forward.y)
        // Composes with (does not replace) the sphere's canonical -90° facing, which lives
        // on the child ModelEntity in SpatialImageEnvironment.makeSphere().
        sceneRoot.orientation = simd_quatf(angle: recenterYaw, axis: [0, 1, 0])
        return true
    }

    // MARK: - Scene selection

    /// Show a specific sky by catalog index, masked by the §7b whiteout flash.
    func selectScene(_ index: Int) {
        let n = SpatialImageEnvironment.catalog.count
        guard n > 0 else { return }
        let idx = ((index % n) + n) % n
        currentScene = idx
        UserDefaults.standard.set(
            SpatialImageEnvironment.catalog[idx].name, forKey: Self.lastSceneKey)
        maskedSwap { [weak self] in self?.applyScene(idx) }
    }

    /// Jump to a random *different* sky. Uses a shuffle bag so every sky is visited once
    /// before any repeat (independent random draws clustered on a few). No determinism
    /// requirement here — this is a user action, not generation (§5 applied to the retired
    /// generated scene).
    func randomScene() {
        let n = SpatialImageEnvironment.catalog.count
        guard n > 1 else { if n == 1 { selectScene(0) }; return }
        if sceneBag.isEmpty {
            var bag = Array(0..<n).shuffled()
            if bag.last == currentScene { bag.swapAt(0, n - 1) }   // no immediate repeat
            sceneBag = bag
        }
        selectScene(sceneBag.removeLast())
    }

    private var sceneBag: [Int] = []

    /// Load the sky into the sphere. Falls through to the mono skybox if the stereo material
    /// or an eye can't load (SpatialImageEnvironment handles that).
    private func applyScene(_ index: Int) {
        guard let sceneRoot else { return }
        Task { @MainActor in await SpatialImageEnvironment.load(index: index, into: sceneRoot) }
    }

    /// Run `swap` under the peak of the §7b whiteout flash. Applies immediately if the overlay
    /// isn't mounted yet (e.g. a scene chosen from the launcher before entering the space).
    private func maskedSwap(_ swap: @escaping @MainActor () -> Void) {
        guard let whiteout else { swap(); return }
        if whiteout.components[WhiteoutComponent.self]?.active == true { return }
        var c = whiteout.components[WhiteoutComponent.self] ?? WhiteoutComponent()
        c.active = true; c.elapsed = 0
        whiteout.components.set(c)
        Task { @MainActor in
            try? await Task.sleep(for: .seconds(0.30))
            swap()
        }
    }
}

/// Launcher — the flat window that opens the immersive space and gives the three top-level
/// actions: a random sky, the scene picker, and the Entertainment sub-menu (Kindle / Music /
/// Video). Everything scene-related now targets the single spatial-image system.
struct LauncherView: View {
    @Environment(AppModel.self) private var model
    @Environment(\.openImmersiveSpace) private var openImmersiveSpace
    @Environment(\.dismissImmersiveSpace) private var dismissImmersiveSpace
    @Environment(\.openWindow) private var openWindow

    var body: some View {
        VStack(spacing: 16) {
            Text("Float").font(.extraLargeTitle)
            Text("Step into deep space.").foregroundStyle(.secondary)

            Button("Enter") {
                Task {
                    model.immersion = .opening
                    _ = await openImmersiveSpace(id: AppModel.immersiveSpaceID)
                    model.immersion = .open
                }
            }
            .buttonStyle(.borderedProminent)
            .disabled(model.immersion != .closed)

            Button("Random Scene", systemImage: "shuffle") { model.randomScene() }
                .buttonStyle(.bordered)

            Button("Recenter", systemImage: "dot.viewfinder") { model.recenter() }
                .buttonStyle(.bordered)
                .disabled(model.immersion != .open)

            Button("Scenes…", systemImage: "square.grid.2x2") { openWindow(id: "scenes") }
                .buttonStyle(.bordered)

            Button("Entertainment", systemImage: "play.rectangle.on.rectangle") {
                openWindow(id: "entertainment")
            }
            .buttonStyle(.bordered)

            Button("Exit", systemImage: "power", role: .destructive) {
                // Leave cleanly: dismiss the immersive space first, then terminate. A hard
                // exit is fine for a single-user sideloaded app (no App Store review).
                Task {
                    if model.immersion == .open { await dismissImmersiveSpace() }
                    exit(0)
                }
            }
            .buttonStyle(.bordered)
            .padding(.top, 8)
        }
        .padding(40)
        .task {
            // Launch straight into the environment — the menu stays up for Scenes/Exit but
            // shouldn't gate entry. (The in-scene control panel's hand-tracking reveal is
            // still stubbed, so the launcher window must keep existing as the fallback UI.)
            guard model.immersion == .closed else { return }
            // `.opening` BEFORE the decode, not after: preparing now takes seconds, and
            // leaving the state at `.closed` for that long would keep the Enter button
            // live and let a tap start a second open underneath this one.
            model.immersion = .opening
            // Decode the sky FIRST, then open the space, so it comes up populated rather
            // than as black limbo the user waits inside. Same total wait, spent in front of
            // the splash instead. See AppModel.prepareFirstSky().
            await model.prepareFirstSky()
            _ = await openImmersiveSpace(id: AppModel.immersiveSpaceID)
            model.immersion = .open
        }
    }
}

/// Resource names in catalog order — the index space AppModel/`load(index:)` use.
static var resourceNames: [String] { catalog.map(\.name) }

// Must match the authored RCP material (see the package README).
private static let materialSceneName = "Stereo360"          // Stereo360.usda
private static let materialPrimPath  = "/Root/Stereo360"     // material prim path
private static let leftParam  = "LeftEye"
private static let rightParam = "RightEye"

private static let skyboxName = "ImportedSpatial_Skybox"
private static let sphereRadius: Float = 1000

private enum SpatialError: Error { case eyesUnavailable }

/// The container that holds the current imported sky. Created empty (so visibility toggles
/// work immediately); populate/swap with `load(index:into:)`.
@MainActor
static func makeContainer() -> Entity {
    let e = Entity()
    e.name = "ImportedSpatialEnvironment"
    return e
}

/// Swap the container's skybox to `resourceNames[index]`. Tries the stereo material first,
/// falls back to the mono skybox. Removes the previous sky so cycling doesn't stack spheres.
@MainActor
static func load(index: Int, into container: Entity) async {
    guard let sphere = await prepare(index: index) else { return }
    attach(sphere, to: container)
}

/// Build the skybox entity WITHOUT attaching it — the expensive half (HEIC decode,
/// two 12288x6144 texture uploads, the ShaderGraph material) with no scene required.
///
/// Split out so the first sky can be decoded BEFORE the immersive space opens. The old
/// order was: open the space, then start loading into it, which left a real window where
/// the space existed with nothing in it — on device that read as "immersion starts, but
/// it's just flat black". Entities don't need a scene to exist, so the wait can happen
/// while the launcher/splash is still the only thing on screen, and the space can then
/// come up already populated.
@MainActor
static func prepare(index: Int) async -> ModelEntity? {
    let n = resourceNames.count
    let name = resourceNames[((index % n) + n) % n]
    if let stereo = await makeStereoSphere(name: name) { return stereo }
    if let mono = await makeMonoSphere(name: name) { return mono }
    print("[Float] SpatialImageEnvironment: '\(name)' failed to load (stereo + mono)")
    return nil
}

/// Swap a prepared skybox in, removing the previous one so cycling doesn't stack spheres.
@MainActor
static func attach(_ sphere: ModelEntity, to container: Entity) {
    container.children
        .filter { $0.name == skyboxName }
        .forEach { $0.removeFromParent() }
    container.addChild(sphere)
}

// MARK: - Stereo

/// Inward sphere with the `Stereo360` ShaderGraph material, its two eye textures set from
/// the HEIC. Returns nil (→ mono fallback) if the material or either eye can't be loaded.
@MainActor
private static func makeStereoSphere(name: String) async -> ModelEntity? {
    do {
        var material = try await ShaderGraphMaterial(
            named: materialPrimPath, from: materialSceneName, in: realityKitContentBundle)
        // Texture creation also runs detached. TextureResource uploads ~300 MB per eye;
        // awaited from @MainActor the continuation resumes on main and any synchronous
        // portion blocks the frame. If RealityKit ever marks this init MainActor-bound
        // the compiler will reject this and the decode alone (above) is still off-main.
        let textures = try await Task.detached(priority: .userInitiated) {
            let eyes = try await loadEyes(name: name)
            let l = try await TextureResource(image: eyes.left,  options: .init(semantic: .color))
            let r = try await TextureResource(image: eyes.right, options: .init(semantic: .color))
            return StereoTextures(left: l, right: r)
        }.value
        let leftTex = textures.left, rightTex = textures.right
        try material.setParameter(name: leftParam,  value: .textureResource(leftTex))
        try material.setParameter(name: rightParam, value: .textureResource(rightTex))
        return makeSphere(material: material)
    } catch {
        // Expected while the material is still being authored — quiet, mono takes over.
        print("[Float] SpatialImageEnvironment: stereo material unavailable (\(error)) — mono fallback")
        return nil
    }
}

/// CGImage is immutable and thread-safe, but not formally Sendable; this box carries the
/// pair back from the decode task without weakening anything else.
private struct StereoTextures: @unchecked Sendable {
    let left: TextureResource
    let right: TextureResource
}

private struct EyePair: @unchecked Sendable {
    let left: CGImage
    let right: CGImage

    // Persistent container holds the scene; a scene change swaps the sky under it.
    let container = Entity()
    container.name = "SceneContainer"
    content.add(container)
    model.sceneContainer = container

    // The spatial-image environment — an empty container mounted now (so a select
    // works immediately) whose skybox loads async and can be swapped (currentScene).
    let scene = SpatialImageEnvironment.makeContainer()
    container.addChild(scene)
    model.sceneRoot = scene
    if let ready = model.preparedSky {
        // Preloaded by LauncherView before the space opened — attach synchronously
        // so the very first frame of immersion already has the sky in it.
        SpatialImageEnvironment.attach(ready, to: scene)
        model.preparedSky = nil      // consumed; a scene change re-decodes as normal
        model.sceneReady = true
    } else {
        // Preload failed or was skipped — fall back to loading in place. This is the
        // old behaviour, black gap and all, but it only happens if `prepare` returned
        // nil, in which case there is nothing to show either way.
        Task { @MainActor in
            await SpatialImageEnvironment.load(index: model.currentScene, into: scene)
            model.sceneReady = true  // drops SplashView (see AppModel.sceneReady)
        }
    }

    // §7b whiteout overlay — a persistent inward white sphere (alpha 0) a jump flashes.
    let whiteout = WhiteoutSystem.makeEntity()
    container.addChild(whiteout)
    model.whiteout = whiteout

    // Hidden control panel, revealed by the two-hand pinch-spread gesture (§7).
    if let panel = attachments.entity(for: "controlPanel") {
        panel.isEnabled = false
        container.addChild(panel)
    }
} update: { _, _ in
    // Scene changes are driven imperatively via AppModel (it mutates the container).
} attachments: {
    Attachment(id: "controlPanel") {
        ControlPanelView().environment(model)
    }
}
.task { await runHandTracking() }    // §7 reveal gesture

