struct WhiteoutComponent: Component {
    var active = false
    var elapsed: TimeInterval = 0
    var fadeIn: TimeInterval = 0.25
    /// MINIMUM time parked at full black. The overlay stays at peak past this for as long as
    /// `holding` is true.
    var hold: TimeInterval = 0.12
